files.examples/01_named_query.sql:
-- LEARN(sql.server-side.views): a view stores a query, never rows.
CREATE TABLE requirements (
  id    int  PRIMARY KEY,
  code  text NOT NULL UNIQUE,
  title text NOT NULL
);
CREATE TABLE test_cases (
  id             int  PRIMARY KEY,
  requirement_id int  NOT NULL REFERENCES requirements,
  status         text NOT NULL  -- result of the latest run
);
INSERT INTO requirements VALUES
  (1, 'REQ-LOGIN', 'Kullanıcı girişi'),
  (2, 'REQ-EXPORT', 'CSV dışa aktarım'),
  (3, 'REQ-AUDIT', 'Denetim izi');
INSERT INTO test_cases VALUES (10, 1, 'passed'), (11, 1, 'failed'), (12, 2, 'passed');

-- One definition of "coverage" for every report, endpoint and psql session.
CREATE VIEW requirement_coverage AS
SELECT r.code,
       count(t.id) AS tests,
       count(t.id) FILTER (WHERE t.status = 'passed') AS passed
FROM requirements r
LEFT JOIN test_cases t ON t.requirement_id = r.id
GROUP BY r.id, r.code;

SELECT * FROM requirement_coverage WHERE passed < tests OR tests = 0 ORDER BY code;

-- The planner expands the view like a macro and pushes the filter down.
EXPLAIN (COSTS OFF) SELECT * FROM requirement_coverage WHERE code = 'REQ-LOGIN';

-- SELECT * is expanded once, when the view is created.
CREATE VIEW requirement_list AS SELECT * FROM requirements;
ALTER TABLE requirements ADD COLUMN priority int NOT NULL DEFAULT 2;
SELECT * FROM requirement_list ORDER BY id;
SELECT trim(regexp_replace(pg_get_viewdef('requirement_list'::regclass), '\s+', ' ', 'g')) AS stored_query;

-- Views pin the columns they use.
ALTER TABLE test_cases ALTER COLUMN status TYPE varchar(10);

files.examples/02_updatable.sql:
CREATE TABLE test_cases (
  id         int  PRIMARY KEY,
  project_id int  NOT NULL,
  title      text NOT NULL,
  status     text NOT NULL
);
INSERT INTO test_cases VALUES
  (1, 1, 'Giriş', 'failed'), (2, 1, 'Çıkış', 'passed'), (3, 2, 'Fatura', 'failed');

-- One table, no aggregates, DISTINCT or LIMIT: automatically updatable.
CREATE VIEW project1_cases AS
SELECT id, project_id, title, status FROM test_cases WHERE project_id = 1;

-- Writes through the view see only the view's rows.
UPDATE project1_cases SET status = 'retest' WHERE status = 'failed';
SELECT id, project_id, status FROM test_cases ORDER BY id;

-- Without a check option, the view accepts rows it would not show.
INSERT INTO project1_cases VALUES (4, 2, 'Rapor', 'failed');
SELECT count(*) AS visible_through_view FROM project1_cases WHERE id = 4;

-- WITH CHECK OPTION: every written row must satisfy the view's WHERE.
CREATE OR REPLACE VIEW project1_cases AS
SELECT id, project_id, title, status FROM test_cases WHERE project_id = 1
WITH CHECK OPTION;
UPDATE project1_cases SET status = 'passed' WHERE id = 1;
UPDATE project1_cases SET project_id = 2 WHERE id = 2;

files.examples/03_materialized.sql:
-- A materialized view runs its query once and stores the result.
A: CREATE MATERIALIZED VIEW pass_rates AS
   SELECT requirement, count(*) AS runs, count(*) FILTER (WHERE passed) AS passed
   FROM test_runs
   GROUP BY requirement;
A: CREATE UNIQUE INDEX ON pass_rates (requirement);

-- New runs arrive; the stored rows don't change until a refresh.
B: INSERT INTO test_runs (requirement, passed) VALUES ('REQ-LOGIN', true);
B: SELECT * FROM pass_rates ORDER BY requirement;

-- A plain REFRESH rebuilds it under an ACCESS EXCLUSIVE lock: readers wait.
A: BEGIN;
A: REFRESH MATERIALIZED VIEW pass_rates;
B: SELECT * FROM pass_rates ORDER BY requirement;
A: COMMIT;

-- CONCURRENTLY computes the new result, diffs it against the stored one
-- and applies the difference; readers keep seeing the old rows meanwhile.
B: INSERT INTO test_runs (requirement, passed) VALUES ('REQ-EXPORT', false);
A: BEGIN;
A: REFRESH MATERIALIZED VIEW CONCURRENTLY pass_rates;
B: SELECT * FROM pass_rates ORDER BY requirement;
A: COMMIT;
B: SELECT * FROM pass_rates ORDER BY requirement;
